-- Additive optional preference scene. No content, snapshot, receipt or history rows are rewritten.
-- Stop writers and settle IO before applying. Existing function ACLs are preserved by OR REPLACE.
LOCK TABLE qf.quizpack_import,qf.quizpack_validation,qf.product_asset,qf.draft_revision,qf.product_version,qf.internal_play_version,qf.access_key,qf.consumer_session,qf.consumer_grant,qf.quiz_report IN SHARE ROW EXCLUSIVE MODE NOWAIT;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND usename=replace(current_user,'qf_owner_','qf_app_') AND pid<>pg_backend_pid()) THEN RAISE EXCEPTION 'D3_WRITERS_PRESENT' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM qf.quizpack_import WHERE status='receiving' OR storage_condition<>'clean' OR reserved_bytes<>0 OR lease_until IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(attempts) a WHERE a->>'disposition'<>'released'))
 OR EXISTS(SELECT 1 FROM qf.quizpack_validation WHERE status IN ('validating','archiving') OR storage_condition<>'clean' OR reserved_bytes<>0 OR lease_until IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(attempts_text::jsonb) a WHERE a->>'disposition'<>'released' OR a->>'mediaStop'='unconfirmed'))
 THEN RAISE EXCEPTION 'D3_UNSETTLED_IO' USING ERRCODE='55000'; END IF;
END $$;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.consumer_schema_v2(text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='70d2aceb25a07b9964066f39609c99d5c49d991ca29dc20612cb7827de01625a' AND provolatile='i' AND proisstrict AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='jsonb'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='sql') AND proconfig=ARRAY['search_path=pg_catalog'])
 OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.composed_assets_v1(jsonb,jsonb)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='f1c46abc24797c3bbb8bf73c6a9fbbf46fa5619a6f9c475f22f0187c79d48172' AND provolatile='i' AND proisstrict AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='jsonb'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog'])
 OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid IN ('qf.consumer_schema_v2(text)'::regprocedure,'qf.composed_assets_v1(jsonb,jsonb)'::regprocedure) AND a.grantee=0)
 THEN RAISE EXCEPTION 'D3_PREVIOUS_HELPER_CHANGED' USING ERRCODE='55000'; END IF;
END $$;

CREATE OR REPLACE FUNCTION qf.consumer_schema_v2(kind text) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $schema$ SELECT CASE kind
